constexpr size_t budget=64u*1024u*1024u;
void real(SnapshotWriter& out,float value){if(!std::isfinite(value))throw std::runtime_error("Invalid effect real");out.u32(std::bit_cast<std::uint32_t>(value));}
float real(Binary& in){auto value=std::bit_cast<float>(in.u32());if(!std::isfinite(value))throw std::runtime_error("Invalid effect real");return value;}
void time(SnapshotWriter& out,double value){if(!std::isfinite(value))throw std::runtime_error("Invalid effect time");out.u64(std::bit_cast<std::uint64_t>(value));}
double time(Binary& in){auto value=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(value))throw std::runtime_error("Invalid effect time");return value;}
void optionalTime(SnapshotWriter& out,const std::optional<double>& value){out.u32(value?1:0);if(value)time(out,*value);}
std::optional<double> optionalTime(Binary& in){auto present=in.u32();if(present>1)throw std::runtime_error("Invalid effect optional time");return present?std::optional<double>(time(in)):std::nullopt;}
bool flag(Binary& in){auto value=in.u32();if(value>1)throw std::runtime_error("Invalid effect flag");return value!=0;}
struct SavedEffect {std::uint32_t stable=0;bool alive=false;std::optional<ScriptEffect> visual;};
