    std::vector<std::uint32_t> ids;for(auto& [id,effect]:effects_)if(id&0x80000000u)ids.push_back(id);if(ids.size()>8192)throw std::runtime_error("Spider visual count exceeds budget");out.size(ids.size());for(auto id:ids){auto e=effects_.at(id);if(!e || e->id!=id || !(id&0x7fffffffu) || (id&0x7fffffffu)>spiderVisualId_ || (!spiderAttackVisuals_.contains(id) && !e->destroyed))throw std::runtime_error("Invalid spider visual identity");out.u32(id);unit(e->target);for(auto* text:{&e->model,&e->attachment,&e->texture,&e->sequenceSuffix})out.text(*text,65536);out.u32(e->replacement);out.u32(e->teamColor?1:0);if(e->teamColor)out.u32(*e->teamColor);out.u32(e->tint);real(out,std::bit_cast<float>(e->point.x.bits()));real(out,std::bit_cast<float>(e->point.y.bits()));for(auto value:{e->z,e->facing,e->scale})real(out,value);out.u32(e->moonWellWaterHeight?1:0);if(e->moonWellWaterHeight)real(out,*e->moonWellWaterHeight);time(out,e->born);optionalTime(out,e->destroyed);optionalTime(out,e->expires);optionalTime(out,e->fallbackExpires);for(bool value:{e->automatic,e->groundAnchor,e->hideWhenDead})out.u32(value?1:0);}
